&lt;li style=&quot;font-size: 16px;&quot;&gt;&lt;span style=&quot;font-size: 16px;&quot;&gt;401k, tuition reimbursement and student loan paydown plans&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 16px;&quot;&gt;&lt;span style=&quot;font-size: 16px;&quot;&gt;Employee Stock Purchase Plan&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 16px;&quot;&gt;&lt;span style=&quot;font-size: 16px;&quot;&gt;Fertility and adoption support and up to 18 weeks of paid parental leave&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 16px;&quot;&gt;&lt;span style=&quot;font-size: 16px;&quot;&gt;Child care and family care discounts&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 16px;&quot;&gt;&lt;span style=&quot;font-size: 16px;&quot;&gt;Free access to Peloton Digital App and apparel and product discounts&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 16px;&quot;&gt;&lt;span style=&quot;font-size: 16px;&quot;&gt;Commuter benefits and Citi Bike Discount&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 16px;&quot;&gt;&lt;span style=&quot;font-size: 16px;&quot;&gt;Pet insurance and so much more!&lt;/span&gt;&lt;/li&gt;
